INSERT INTO products (seller_id, name, description, price, stock_qty, category, image_url) VALUES
(2, 'Plush Teddy Bear', 'A soft, cuddly teddy bear made from premium plush fabric with embroidered eyes and a stitched smile, perfect as a gift or bedtime companion for kids of all ages.', 599.00, 220, 'Toys', 'https://images.pexels.com/photos/34967760/pexels-photo-34967760.jpeg'),
(2, 'Remote Control Race Car', 'A high-speed remote control race car built for smooth handling and durability, featuring responsive steering, sturdy tires, and a rechargeable battery for hours of play.', 1099.00, 150, 'Toys', 'https://images.pexels.com/photos/37117113/pexels-photo-37117113.jpeg'),
